    t = integer_one_കണ്ണി;

  check_no_duplicate_clause (list, OMP_CLAUSE_INDIRECT, "indirect");

  വൃക്ഷം c = build_omp_clause (location, OMP_CLAUSE_INDIRECT);
  OMP_CLAUSE_INDIRECT_വ്യഞ്ജകം (c) = t;
  OMP_CLAUSE_CHAIN (c) = list;

