  വൃക്ഷം append_args_last;
  vec<വൃക്ഷം> adjust_args_list = vNULL;
  തർക്കം has_match = അസത്യം, has_adjust_args = അസത്യം;
  location_t adjust_args_loc = UNKNOWN_LOCATION;
  location_t append_args_loc = UNKNOWN_LOCATION;
  location_t match_loc = UNKNOWN_LOCATION;
  വൃക്ഷം need_device_ptr_list = NULL_വൃക്ഷം;
  വൃക്ഷം ctx = error_mark_കണ്ണി;

